//! Chat endpoints. POST streams SSE messages, each one `ChatSseEvent`.
//! Persistence is all-or-nothing after the stream
//! completes; replies are generated by the agent sidecar (`src/agent`).

use anyhow::Context as _;
use axum::extract::State;
use axum::http::StatusCode;
use axum::response::sse::{Event, KeepAlive, Sse};
use axum::response::{IntoResponse, Response};
use axum::routing::get;
use axum::{Json, Router};
use futures_util::StreamExt;
use serde::{Deserialize, Serialize};
use ts_rs::TS;

use super::fetch_paper;
use crate::agent::ask::{AskRequest, ToolCall, TurnEvent};
use crate::app::{App, Trash};
use crate::web::error::ApiError;
use crate::web::extract::{ApiJson, ApiPath};

pub(super) fn routes() -> Router<App> {
    Router::new().route("/api/chat/models", get(models)).route(
        "/api/papers/{id}/chat",
        get(history).post(send).delete(clear),
    )
}

/// GET /api/chat/models response.
#[derive(Serialize, TS)]
#[ts(export)]
struct ChatModels {
    available: bool,
    models: Vec<ChatModel>,
}

#[derive(Serialize, TS)]
#[ts(export, rename = "ChatModelInfo")]
struct ChatModel {
    id: String,
    label: String,
}

/// One stored chat turn as GET /api/papers/{id}/chat returns it (the
/// frontend's `ChatTurnRow`). The store's `tools_json` TEXT is parsed
/// server-side, once, so the wire carries the tool log structured — the same
/// shape the live SSE `tool` events use — instead of a JSON string the client
/// would have to re-parse.
#[derive(Serialize, TS)]
#[ts(export, rename = "ChatTurnRow")]
struct ChatTurn {
    id: i64,
    role: crate::agent::history::ChatRole,
    content: String,
    model: Option<String>,
    created_at: String,
    tools: Option<Vec<ToolCall>>,
}

impl From<crate::agent::history::ChatMessageRow> for ChatTurn {
    fn from(r: crate::agent::history::ChatMessageRow) -> Self {
        let tools = r.tools();
        Self {
            id: r.id,
            role: r.role,
            content: r.content,
            model: r.model,
            created_at: r.created_at,
            tools,
        }
    }
}

#[derive(Deserialize, TS)]
#[ts(export)]
struct ChatRequest {
    model_id: String,
    message: String,
}

/// One SSE message of a streaming reply: `tool` and `delta` events, then
/// `done` (with the stored assistant turn's id) or `error`.
#[derive(Serialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
#[ts(export)]
enum ChatSseEvent {
    Delta { text: String },
    Tool(ToolCall),
    Error { message: String },
    Done { id: i64 },
}

impl From<TurnEvent> for ChatSseEvent {
    fn from(ev: TurnEvent) -> Self {
        match ev {
            TurnEvent::Delta(text) => Self::Delta { text },
            TurnEvent::Tool(call) => Self::Tool(call),
            TurnEvent::Error(message) => Self::Error { message },
            TurnEvent::Done(id) => Self::Done { id },
        }
    }
}

async fn models(State(app): State<App>) -> Json<ChatModels> {
    match app.agent().ok() {
        None => Json(ChatModels {
            available: false,
            models: Vec::new(),
        }),
        Some(a) => Json(ChatModels {
            available: true,
            models: a
                .backends
                .iter()
                .map(|b| ChatModel {
                    id: b.id.clone(),
                    label: b.label.clone(),
                })
                .collect(),
        }),
    }
}

async fn history(
    State(app): State<App>,
    ApiPath(id): ApiPath<String>,
) -> Result<Response, ApiError> {
    let paper = fetch_paper(&app, &id, Trash::Deny, "chat").await?;
    let rows = crate::agent::history::list(app.pool(), &paper.id)
        .await
        .context("chat history")?;
    let turns: Vec<ChatTurn> = rows.into_iter().map(ChatTurn::from).collect();
    Ok(Json(turns).into_response())
}

async fn clear(State(app): State<App>, ApiPath(id): ApiPath<String>) -> Result<Response, ApiError> {
    let paper = fetch_paper(&app, &id, Trash::Deny, "chat").await?;
    crate::agent::history::clear(app.pool(), &paper.id)
        .await
        .context("chat clear")?;
    Ok(StatusCode::NO_CONTENT.into_response())
}

async fn send(
    State(app): State<App>,
    ApiPath(id): ApiPath<String>,
    ApiJson(req): ApiJson<ChatRequest>,
) -> Result<Response, ApiError> {
    app.agent()?;
    let paper = fetch_paper(&app, &id, Trash::Deny, "chat").await?;
    let turn = app
        .ask(
            &paper,
            AskRequest {
                model_id: req.model_id,
                message: req.message,
            },
        )
        .await?;
    let stream = turn.map(|ev| Event::default().json_data(ChatSseEvent::from(ev)));
    Ok(Sse::new(stream)
        .keep_alive(KeepAlive::default())
        .into_response())
}
